Use a circular buffer with capacity 17; reject a push when it is full without changing the queue. The invariant is `0 <= size <= 17`, with `head` pointing to the next element to pop and logical element `i` stored at `(head + i) % 17`; the next push goes to `(head + size) % 17`. A successful push increments `size`, while a successful pop advances `head` modulo 17 and decrements `size`, preserving FIFO order.

Here is a complete C++17 implementation for integer values. `push` returns false on overflow, and `pop` returns an empty optional on underflow.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) {
            return false;
        }
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        int value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

void check(bool condition, const char* message) {
    if (!condition) {
        throw std::runtime_error(message);
    }
}

int main() {
    BoundedFIFO q;
    check(!q.pop().has_value(), "Initial underflow failed");

    // Fill all 17 slots, then reject overflow.
    for (int i = 0; i < 17; ++i) {
        check(q.push(i), "Fill failed");
    }
    check(q.full(), "Queue should be full");
    check(!q.push(999), "Overflow should be rejected");
    check(q.size() == 17, "Overflow changed size");

    // Drain and verify that overflow did not alter FIFO contents.
    for (int i = 0; i < 17; ++i) {
        auto value = q.pop();
        check(value.has_value() && *value == i, "Drain order failed");
    }
    check(q.empty(), "Queue should be empty");
    check(!q.pop().has_value(), "Underflow should be rejected");

    // Move head to slot 5, leaving values 5 through 9 queued.
    for (int i = 0; i < 10; ++i) {
        check(q.push(i), "Wrap setup push failed");
    }
    for (int i = 0; i < 5; ++i) {
        auto value = q.pop();
        check(value.has_value() && *value == i, "Wrap setup pop failed");
    }

    // Add 12 values: writes cross slot 16 and wrap to slot 0.
    for (int i = 10; i < 22; ++i) {
        check(q.push(i), "Wrapped push failed");
    }
    check(q.full(), "Wrapped queue should be full");
    check(!q.push(999), "Wrapped overflow should be rejected");

    // The 17 remaining values must still be 5 through 21.
    for (int i = 5; i < 22; ++i) {
        auto value = q.pop();
        check(value.has_value() && *value == i, "Wrapped FIFO order failed");
    }
    check(q.empty(), "Final queue should be empty");
    check(!q.pop().has_value(), "Final underflow failed");
    std::cout << "All tests passed\n";
}
```

